let pg1, pg2, pg3;
let lastGeom = '', lastDens = '', lastPal = '';
let phase1 = 0, phase2 = 1000, phase3 = 2000;

const densityMap = {
  'Gauze Coarse': 24,
  'Linen Open Weave': 16,
  'Muslin Balanced': 10,
  'Organza Crisp': 7,
  'Habotai Sheer': 5,
  'Microfilament Shimmer': 3.5
};

const weftMap = {
  'Parallel Drift 0deg': 0,
  'Acute Shear 12deg': 12,
  'Bias Crossed 30deg': 30,
  'Rhombic Angle 45deg': 45,
  'Orthogonal Grid 60deg': 60,
  'Antagonistic Opposition 90deg': 90
};

const tempoMap = {
  'Glacial Suspension': 0.1,
  'Tidal Float': 0.3,
  'Whispering Breeze': 0.7,
  'Rolling Surge': 1.5,
  'Fluttering Thermal': 2.8,
  'Turbulent Churn': 5.0
};

const paletteMap = {
  'Raw Silk & Bone': { bg: '#EAE6DF', c1: 'rgba(200, 190, 180, 0.75)', c2: 'rgba(160, 150, 140, 0.75)', c3: 'rgba(130, 120, 110, 0.75)', blend: 'multiply' },
  'Chartreuse & Slate': { bg: '#D1E231', c1: 'rgba(112, 128, 144, 0.8)', c2: 'rgba(80, 100, 120, 0.8)', c3: 'rgba(47, 79, 79, 0.8)', blend: 'multiply' },
  'Indigo Smoke & Copper': { bg: '#0A1526', c1: 'rgba(184, 115, 51, 0.85)', c2: 'rgba(120, 140, 150, 0.85)', c3: 'rgba(80, 100, 110, 0.85)', blend: 'screen' },
  'Madder Root & Ochre': { bg: '#2A0809', c1: 'rgba(204, 119, 34, 0.85)', c2: 'rgba(180, 80, 40, 0.85)', c3: 'rgba(139, 58, 58, 0.85)', blend: 'screen' },
  'Iridescent Beetle Wing': { bg: '#081208', c1: 'rgba(75, 0, 130, 0.85)', c2: 'rgba(0, 250, 154, 0.85)', c3: 'rgba(50, 100, 200, 0.85)', blend: 'screen' },
  'Obsidian & Ultraviolet': { bg: '#050505', c1: 'rgba(94, 16, 181, 0.9)', c2: 'rgba(120, 40, 200, 0.9)', c3: 'rgba(40, 10, 80, 0.9)', blend: 'screen' }
};

p.setup = function() {
  p.createCanvas(800, 800);
  // Smaller 1000x1000 buffers, will be stretched to 1400x1400 to preserve edge coverage
  pg1 = p.createGraphics(1000, 1000);
  pg2 = p.createGraphics(1000, 1000);
  pg3 = p.createGraphics(1000, 1000);
};

p.draw = function() {
  const vGeom = p.getSynthVar('warp_geometry') || 'Parallel Strands';
  const vDens = p.getSynthVar('thread_density') || 'Gauze Coarse';
  const vRot = p.getSynthVar('weft_rotation') || 'Parallel Drift 0deg';
  const vSpd = p.getSynthVar('drift_tempo') || 'Glacial Suspension';
  const vPal = p.getSynthVar('organza_palette') || 'Raw Silk & Bone';

  if (vGeom !== lastGeom || vDens !== lastDens || vPal !== lastPal) {
    rebuildFabrics(vGeom, vDens, vPal);
    lastGeom = vGeom;
    lastDens = vDens;
    lastPal = vPal;
  }

  const speed = tempoMap[vSpd];
  phase1 += speed * 0.3 + 0.0137;
  phase2 += speed * 0.45 + 0.0173;
  phase3 += speed * 0.35 + 0.0191;

  const angleBase = p.radians(weftMap[vRot]);
  const pal = paletteMap[vPal];

  p.background(pal.bg);
  p.drawingContext.globalCompositeOperation = pal.blend;
  p.imageMode(p.CENTER);

  // Layer 1
  p.push();
  p.translate(400 + p.cos(phase1 * 0.01) * 100, 400 + p.sin(phase1 * 0.011) * 100);
  p.image(pg1, 0, 0, 1400, 1400);
  p.pop();

  // Layer 2
  p.push();
  p.translate(400 + p.cos(phase2 * 0.013) * 120, 400 + p.sin(phase2 * 0.014) * 120);
  p.rotate(angleBase);
  p.image(pg2, 0, 0, 1400, 1400);
  p.pop();

  // Layer 3
  p.push();
  p.translate(400 + p.cos(-phase3 * 0.012) * 90, 400 + p.sin(phase3 * 0.015) * 90);
  p.rotate(-angleBase);
  p.image(pg3, 0, 0, 1400, 1400);
  p.pop();

  // Reset to default
  p.drawingContext.globalCompositeOperation = 'source-over';
};

function rebuildFabrics(vGeom, vDens, vPal) {
  const baseD = densityMap[vDens];
  const pal = paletteMap[vPal];
  const d = baseD * (1000 / 1400); // Scale rendering density to match smaller buffer
  renderFabric(pg1, vGeom, d, pal.c1);
  renderFabric(pg2, vGeom, d, pal.c2);
  renderFabric(pg3, vGeom, d, pal.c3);
}

function renderFabric(pg, geom, d, col) {
  pg.clear();
  pg.noFill();
  pg.stroke(col);
  pg.strokeWeight(Math.max(1.0, d * 0.4));

  const s = 1000;
  const c = s / 2;

  if (geom === 'Parallel Strands') {
    pg.beginShape(p.LINES);
    for (let y = 0; y <= s; y += d) {
      pg.vertex(0, y);
      pg.vertex(s, y);
    }
    pg.endShape();
  } 
  else if (geom === 'Gentle Sine Swell') {
    for (let y = -150; y <= s + 150; y += d) {
      pg.beginShape();
      for (let x = 0; x <= s; x += 30) {
        pg.vertex(x, y + p.sin((x * 0.007) + (y * 0.014)) * 85);
      }
      pg.endShape();
    }
  } 
  else if (geom === 'Concentric Arc Ripple') {
    const maxR = s * 1.5;
    for (let r = d; r <= maxR; r += d) {
      pg.ellipse(c, c, r, r);
    }
  } 
  else if (geom === 'Bi-directional Chevron') {
    for (let y = -75; y <= s + 75; y += d) {
      pg.beginShape();
      for (let x = 0; x <= s + 60; x += 60) {
        pg.vertex(x, y + ((x / 60) % 2 === 0 ? 21 : -21));
      }
      pg.endShape();
    }
  } 
  else if (geom === 'Compressed Hyperbola') {
    // Tightened bounds from -s to -400 to save vertices outside the visible diagonal
    for (let y = -400; y <= s + 400; y += d) {
      pg.beginShape();
      for (let x = 0; x <= s; x += 40) {
        let dx = x - c;
        let dy = p.sqrt(dx * dx + 25000) * (y < c ? -0.4 : 0.4);
        pg.vertex(x, y + dy);
      }
      pg.endShape();
    }
  } 
  else if (geom === 'Radial Pinwheel Lattice') {
    const steps = (p.TWO_PI * c) / d;
    const angleStep = p.TWO_PI / Math.max(10, steps);
    for (let a = 0; a < p.TWO_PI; a += angleStep) {
      pg.beginShape();
      for (let r = 0; r <= s; r += 30) {
        let twist = r * 0.0021;
        pg.vertex(c + p.cos(a + twist) * r, c + p.sin(a + twist) * r);
      }
      pg.endShape();
    }
  }
}
